-- strapi-php 5.56 getstarted on PostgreSQL 16: the admin tables and locales after
-- registering the first admin and adding a "Content Writer" role with the SQLite fixture's
-- permissions; columns the reader skips are left out.
CREATE TABLE admin_roles (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, document_id varchar(255), name varchar(255), code varchar(255), description varchar(255));
CREATE TABLE admin_permissions (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, document_id varchar(255), action varchar(255), action_parameters jsonb, subject varchar(255), properties jsonb, conditions jsonb);
CREATE TABLE admin_permissions_role_lnk (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, permission_id integer, role_id integer, permission_ord double precision);
CREATE TABLE i18n_locale (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, document_id varchar(255), name varchar(255), code varchar(255));
